// Simulation of Loader Action during Dynamic Relocation

// Runtime Base Address (where the program actually landed)
long RuntimeLoadBase = 0x80000000;

// Data extracted from the Relocation Table (e.g., ELF Rela struct)
long SymbolValue = 0x00010500; // S: Compiled address of the target symbol
int  Addend      = 4;          // A: Offset stored in the instruction
long PatchOffset = 0x00020100; // r_offset: Location within the segment to patch

// Calculate the address in memory needing the patch
long* PatchLocation = (long*)(RuntimeLoadBase + PatchOffset);

// Relocation Formula: New Address = S + A + P(or L)
long FinalTargetAddress = SymbolValue + Addend + RuntimeLoadBase;

// The Loader applies the relocation patch
*PatchLocation = FinalTargetAddress;

// Now, the instruction points correctly to the runtime target
// *(RuntimeLoadBase + PatchOffset) == 0x80010504
// (if PatchLocation holds a pointer to a 64-bit address)
